	// conflict and must leave the healthy record untouched.
	if out := reportHealth(t, r, "svc", "i1", 1, newer, false, "再次故障"); out.OK ||
		out.Kind != OutcomeConflict || out.Sequence != newer || out.Revision != 1 {
